def rule_for(family,role):
    if family=='credential_transfer':
        if role=='presenter':return None,'Exact normalized presenter carrier versus private holder_birth is not established; full PrincipalRef and birth bytes32 cannot be implicitly equated. Source provenance does not authorize numeric/principal coercion.'
        if role=='authorized_holder':return ('PrivateResourceRef.holder_birth:bytes32','Select independent source-class private authorized holder_birth, preserving all class/purpose/generation/context constraints; HOST public endpoint-manifest custody is separate.'),None
        if role=='phase':return ('Closed source phase enum','Select ACTIVE from explicit frozen after-view; no execution-state observation or witness result inferred.'),None
        return ('Boolean source exception event','explicit_bootstrap_delivery=FALSE from exact source after outside protected pre-enrollment delivery; no new exception authority granted.'),None
    if family=='bootstrap_path':
        if role=='authorized_HOST_PLATFORM_pre_enrollment_provisioner':return None,'No exact qualified compatible normalized HOST provisioner identity selector/source is established. R is SQL oid in existing source port, while HOST actor is tagged OS/source principal. No SQLoid=OSprincipal coercion or inferred HOST SQL role; this is an existing source/adapter evidence gap, not a new normative choice.'
        if role=='claim.caller':return ('SQL oid projected from tagged PrincipalRef(kind=SQL_ROLE)','Losslessly project caller.sql_role_oid from exact R PrincipalRef, preserving source name/anchor/generation and full tagged provenance. This closes only SQL caller equality port; authorized HOST comparison remains unqualified.'),None
        if role=='claim.phase':return ('Closed OperationClaim phase enum','Select explicit ACTIVE source tag from after-view.'),None
        if role=='claim.operation':return ('Closed fixed-source-operation/forbidden-effect enum','Select PRE_ENROLLMENT_PROVISION exact source tag from after-view, not arbitrary SQL command.'),None
        return ('Typed authority-origin path tag','Select exact HOST_ROOT origin path in source after-view; tag is provenance claim only, never authorization or grant.'),None
    if family in EXHAUSTED:return None,EXHAUSTED[family]
    return RULES.get(family),None
